package com.stark.automation.api.tests;
import com.stark.automation.api.clients.PostClient; import com.stark.automation.api.clients.ProductClient; import com.stark.automation.api.models.request.PostRequest; import com.stark.automation.api.models.response.PostResponse; import io.qameta.allure.Allure; import io.restassured.response.Response; import org.testng.Assert; import org.testng.annotations.Test;
public class PostApiTests { private final PostClient posts = new PostClient(); @Test public void getPostReturnsMappedModel() { PostResponse post = posts.getAsModel(1); Assert.assertEquals(post.id(), 1); Assert.assertFalse(post.title().isBlank()); } @Test public void getProductReturnsExpectedName() { Response response = new ProductClient().get(1); attach(response); Assert.assertEquals(response.statusCode(), 200); Assert.assertEquals(response.jsonPath().getString("title"), "Essence Mascara Lash Princess"); } @Test public void createPostReturnsSubmittedFields() { Response response = posts.create(new PostRequest("Portfolio test", "Safe simulated write", 1)); attach(response); Assert.assertEquals(response.statusCode(), 201); Assert.assertEquals(response.jsonPath().getString("title"), "Portfolio test"); } @Test public void updatePostReturnsNewTitle() { Response response = posts.updateTitle(1, "Updated by automated test"); attach(response); Assert.assertEquals(response.statusCode(), 200); Assert.assertEquals(response.jsonPath().getString("title"), "Updated by automated test"); } @Test public void deletePostReportsDeletedResource() { Response response = posts.delete(1); attach(response); Assert.assertEquals(response.statusCode(), 200); Assert.assertTrue(response.jsonPath().getBoolean("isDeleted")); } private void attach(Response response) { Allure.addAttachment("API response", "application/json", response.asPrettyString(), ".json"); } }
